insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-7ea2d3b08ff3', 'es', 'A1', 'Un acuerdo entre Brasil y España', 'El ministro de educación de Brasil y el embajador de España firmaron un acuerdo muy importante. El acuerdo incluye programas de intercambio y formación. Los dos países quieren ayudar a los profesores y a los estudiantes. La cooperación es una oportunidad para las escuelas.

Unos estudiantes brasileños van a España para estudiar. Unas profesoras españolas vienen a Brasil para enseñar. Las universidades participan en el programa. Las clases son en portugués y en español, pero las lenguas son similares. Los profesores aprenden cosas nuevas.

El portugués y el español son lenguas cercanas. La comunicación es fácil. Los acuerdos como este son excelentes para las personas. La educación es una herramienta útil. Los intercambios son importantes para el futuro.', '[{"answer_index":0,"explanation_pt_br":"O texto diz que eles assinaram ''un acuerdo muy importante''. ''Acuerdo'' é masculino singular, por isso usamos ''un''.","options":["un acuerdo","una escuela","los libros","las clases"],"prompt":"¿Qué firmaron el ministro y el embajador?"},{"answer_index":0,"explanation_pt_br":"Em espanhol, ''acuerdo'' é masculino e no plural se diz ''los acuerdos''. O adjetivo ''buenos'' concorda em gênero e número.","options":["Los acuerdos son buenos.","La acuerdos son buenos.","Las acuerdo son buenos.","El acuerdos son buenos."],"prompt":"¿Cuál frase es correcta según el texto?"},{"answer_index":0,"explanation_pt_br":"O texto diz ''Las universidades...''. ''Universidades'' é feminino e plural, por isso usamos ''las''.","options":["las","la","el","los"],"prompt":"En el texto, ¿qué artículo usamos con ''universidades''?"}]'::jsonb, 0, true)
