insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-590c34babcae', 'es', 'A1', 'La familia de Marta', 'Marta es una mujer española. Vive en Madrid con su familia. Su casa es grande y luminosa. En la casa hay tres habitaciones, dos baños y una cocina moderna. Marta tiene un hijo y una hija.

El hijo se llama Pablo y tiene diez años. La hija se llama Lucía y tiene ocho años. El padre de Marta se llama Juan y es un hombre simpático. La madre de Marta se llama Carmen y es una mujer trabajadora. Los abuelos viven cerca y visitan a la familia los domingos.

Los niños juegan en el parque con los amigos. El fin de semana, la familia come en un restaurante. Todos están felices.', '[{"answer_index":1,"explanation_pt_br":"A palavra ''casa'' é um substantivo feminino singular, por isso usamos o artigo definido ''la''.","options":["el","la","los","las"],"prompt":"¿Cuál es el artículo correcto para la palabra ''casa''?"},{"answer_index":2,"explanation_pt_br":"A palavra ''niño'' é masculina, no plural fica ''niños'', e o artigo definido masculino plural é ''los''.","options":["el","la","los","las"],"prompt":"¿Cuál es el artículo correcto para ''niños''?"},{"answer_index":1,"explanation_pt_br":"A palavra ''mujer'' é feminina singular, por isso usamos o artigo indefinido ''una''.","options":["un","una","unos","unas"],"prompt":"¿Cuál es el artículo indeterminado correcto para ''mujer''?"}]'::jsonb, 0, true)
