insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-b9030cf806c1', 'es', 'A1', 'Un acuerdo de educación entre Brasil y España', 'Brasil y España firman un acuerdo de educación. El ministro de Educación de Brasil y el embajador de España en Brasil firmaron un memorando. Los proyectos son para la formación de profesores y gestores. También hay programas de intercambio para estudiantes y profesores. Una profesora puede viajar a España, y un profesor puede viajar a Brasil. Las universidades brasileñas y españolas participan en el acuerdo.

Los estudiantes aprenden español en Brasil y portugués en España. El idioma no es una barrera porque las raíces lingüísticas son similares. Más de cien mil brasileños viven en España, y muchos españoles viven en Brasil. Este acuerdo es un motor para generar conocimiento científico.

La educación es importante para los dos países. Las familias brasileñas y españolas apoyan la idea. Los profesores están contentos con el acuerdo.', '[{"answer_index":3,"explanation_pt_br":"Universidades é um substantivo feminino e está no plural, por isso usamos o artigo definido feminino plural \"las\".","options":["el","la","los","las"],"prompt":"¿Cuál es el artículo definido para \"universidades\" en el texto?"},{"answer_index":0,"explanation_pt_br":"No masculino, o plural de \"un estudiante\" é \"unos estudiantes\". Em espanhol, usamos \"unos\" para masculino plural indefinido.","options":["unos estudiantes","unas estudiantes","los estudiante","las estudiante"],"prompt":"¿Cuál es el plural de \"un estudiante\"?"},{"answer_index":0,"explanation_pt_br":"\"Profesora\" é um substantivo feminino e está no singular, por isso usamos o artigo indefinido feminino singular \"una\".","options":["Es femenina singular","Es masculina singular","Es femenina plural","Es masculina plural"],"prompt":"En la frase \"Una profesora puede viajar a España\", ¿por qué usamos \"una\"?"}]'::jsonb, 0, true)
