insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-8ad630778c46', 'es', 'A1', 'La escuela de idiomas', 'En la escuela de idiomas hay muchos estudiantes. La biblioteca tiene muchos libros. Los profesores son de España y de Brasil. Una profesora habla español y un profesor habla portugués. Las clases son interesantes y los ejercicios son fáciles.

Hoy los estudiantes leen un libro. El libro tiene historias de América Latina. Las palabras son nuevas, pero los estudiantes usan el diccionario. Después, la clase habla de las vacaciones. Un estudiante quiere visitar Madrid, y una estudiante quiere conocer Buenos Aires.

Los estudiantes practican los artículos: el, la, los, las, un, una. El español es una lengua bonita y las lenguas son importantes.', '[{"answer_index":2,"explanation_pt_br":"O texto diz: ''Una profesora habla español y un profesor habla portugués.'' Portanto, quem fala português é ''un profesor'' (um professor).","options":["Una profesora","Los estudiantes","Un profesor","Las profesoras"],"prompt":"¿Quién habla portugués?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''Hoy los estudiantes leen un libro.'' Portanto, eles leem um livro.","options":["Un libro","Una revista","Los diccionarios","Las cartas"],"prompt":"¿Qué leen los estudiantes?"},{"answer_index":3,"explanation_pt_br":"No final do texto: ''Los estudiantes practican los artículos: el, la, los, las, un, una.'' Esses são os artículos definidos e indefinidos em espanhol.","options":["yo, tú, él, nosotros","uno, dos, tres, cuatro","en, de, con, para","el, la, los, las, un, una"],"prompt":"¿Cuáles son los artículos en español?"}]'::jsonb, 0, true)
