insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-4ee3e2856490', 'es', 'A1', 'En mi casa', '¡Hola! Me llamo Ana y vivo en una casa grande con mi familia. Mi padre es alto y mi madre es baja. Tengo un hermano y una hermana. Mi hermano tiene diez años y mi hermana tiene quince. En nuestra casa hay un perro pequeño y una gata negra. Los animales son muy simpáticos.

En mi casa hay tres habitaciones y dos baños. La cocina es blanca y el salón es cómodo. Las ventanas son grandes y los cuadros son bonitos. También hay un jardín con flores de colores.

Me gusta mucho mi casa porque es luminosa y tranquila. ¿Y tú? ¿Cómo es tu casa?', '[{"answer_index":0,"explanation_pt_br":"No texto, Ana diz: ''Tengo un hermano y una hermana'', ou seja, tem um irmão e uma irmã.","options":["Un hermano y una hermana","Dos hermanos","Dos hermanas","No tiene hermanos"],"prompt":"¿Cuántos hermanos tiene Ana?"},{"answer_index":0,"explanation_pt_br":"O texto afirma: ''La cocina es blanca''. Portanto, a cozinha é branca.","options":["Blanca","Negra","Grande","Cómoda"],"prompt":"¿Cómo es la cocina?"},{"answer_index":0,"explanation_pt_br":"Ana diz: ''hay un perro pequeño y una gata negra''. Assim, ela tem um cachorro e uma gata.","options":["Un perro y una gata","Dos perros","Una gata y un loro","Un pez y un perro"],"prompt":"¿Qué animales tiene Ana?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-6dd8012ad97a', 'es', 'A1', 'Las lenguas de España', 'Hoy en la clase de español, la profesora presenta un libro. El libro se llama ''Las lenguas de España''. En España hay una lengua oficial, el español, y también hay otras lenguas: el asturiano, el gallego y el catalán. Las lenguas son importantes para la cultura.

Los estudiantes leen un texto sobre un acuerdo entre Brasil y España. Los ministros firman unos documentos. El acuerdo es para la educación. Un profesor de Brasil y una profesora de España intercambian ideas. Los estudiantes aprenden con las palabras.

En español, los artículos tienen género y número. El y la son singulares; los y las son plurales. Un y una son indefinidos; unos y unas son plurales. Las palabras terminadas en -o son masculinas, y las terminadas en -a son femeninas. ¡Es una regla muy útil!', '[{"answer_index":0,"explanation_pt_br":"O artigo definido plural feminino em espanhol é ''las'' (por exemplo, las lenguas).","options":["las","los","la","el"],"prompt":"¿Cuál es el artículo definido plural femenino?"},{"answer_index":1,"explanation_pt_br":"''Un'' é o artigo indefinido singular masculino (por exemplo, un libro).","options":["el","un","los","una"],"prompt":"En el texto, ¿qué palabra es un artículo indefinido singular masculino?"},{"answer_index":1,"explanation_pt_br":"No texto, diz que as palavras terminadas em -a são femininas (por exemplo, lengua).","options":["-o","-a","-e","-s"],"prompt":"Según el texto, ¿cuál es la terminación de las palabras femeninas?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-92cf2820af04', 'es', 'A1', 'Un día de lenguas', 'La escuela de Ana organiza un día de lenguas. Los estudiantes de la clase de español participan con carteles, libros y banderas. Ana muestra un libro de cuentos. El libro es rojo y tiene muchas imágenes. Los estudiantes hablan de los países hispanohablantes. La maestra explica las diferencias entre el español y el portugués.

En el patio, las banderas de los países están en una mesa. Unos niños leen las palabras en español. Otros niños escriben frases en portugués. El director de la escuela abre el evento con un discurso. Dice: "Las lenguas son importantes para la comunicación y la cultura".

Al final, los estudiantes reciben un certificado. La clase de Ana gana un premio por el mejor cartel. Todos están felices porque aprenden algo nuevo sobre las palabras y los idiomas.', '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Ana muestra un libro de cuentos.'' Por isso, a resposta correta é ''Un libro de cuentos''.","options":["Un libro de cuentos","Una bandera","Un certificado","Un cartel"],"prompt":"¿Qué muestra Ana en el día de lenguas?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''El libro es rojo y tiene muchas imágenes.'' Portanto, ''rojo'' é a cor do livro.","options":["Azul","Rojo","Verde","Amarillo"],"prompt":"¿Cómo es el libro de Ana?"},{"answer_index":0,"explanation_pt_br":"''Banderas'' é um substantivo feminino plural, por isso usamos ''las'' como artigo definido feminino plural (las banderas).","options":["las","los","un","el"],"prompt":"En la frase ''Las banderas de los países están en una mesa'', ¿cuál es el artículo femenino plural?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-es-a1-6546f5a4dc89', 'es', 'A1', 'Un acuerdo entre Brasil y España', 'Brasil y España firman un acuerdo de educación. El ministro de Educación de Brasil y el embajador de España participan en la ceremonia. Los dos países quieren compartir sus conocimientos. El acuerdo incluye programas de intercambio para estudiantes y profesores. Muchos españoles viven en Brasil y muchos brasileños viven en España. El idioma no es una barrera. Las universidades tienen proyectos nuevos. Los profesores pueden trabajar juntos en investigaciones. Los estudiantes pueden aprender en otro país. Es una oportunidad única para la ciencia y la cultura.

El acuerdo también incluye seminarios y conferencias. Los investigadores pueden compartir ideas. Los programas son para estudiantes de licenciatura, máster y doctorado. Las instituciones educativas están contentas con el plan. El memorando fue firmado en 2018. La colaboración continúa hoy. Los jóvenes tienen más opciones para su futuro. Las familias pueden acompañar a sus hijos en esta experiencia.', '[{"answer_index":0,"explanation_pt_br":"A palavra ''oportunidad'' é feminina, por isso o plural correto é ''las oportunidades''.","options":["las oportunidades","los oportunidades","la oportunidad","las oportunidads"],"prompt":"¿Cuál es el plural de ''la oportunidad''?"},{"answer_index":1,"explanation_pt_br":"A palavra ''estudiantes'' é plural e usa-se o artigo masculino plural ''los'' para se referir a um grupo geral.","options":["El","Los","La","Las"],"prompt":"Complete con el artículo correcto: ''____ estudiantes son inteligentes.''"},{"answer_index":1,"explanation_pt_br":"A palavra ''acuerdo'' é masculina singular, portanto o artigo correto é ''el''.","options":["La acuerdo es importante.","El acuerdo es importante.","Los acuerdo son importantes.","Las acuerdo son importantes."],"prompt":"¿Qué frase tiene el artículo definido correcto?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();
